// Parse incoming lead data
const lead = $input.first().json;

// Enrich: generate engagement score
let score = 0;
if (lead.company) score += 10;
if (lead.yearsExperience > 5) score += 15;
if (lead.gigaProjectInterest) score += 20;
if (lead.employerSponsorship) score += 25;

// Determine priority
let priority = 'Low';
if (score >= 50) priority = 'High';
else if (score >= 30) priority = 'Medium';

// Set next action based on ICP
let nextAction = 'Email';
if (lead.icpSegment === 'HR/L&D') nextAction = 'LinkedIn';
if (lead.channel === 'B2B') nextAction = 'Phone';

return [{
  json: {
    ...lead,
    engagementScore: score,
    priority: priority,
    nextActionType: nextAction,
    enrichedAt: new Date().toISOString(),
    status: 'New'
  }
}];
